def monotonic(l: list):
    """Return True is list elements are monotonically increasing or decreasing.
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if len(l) <= 1:
        return True

    direction = 1 if l[0] < l[1] else -1
    for i in range(1, len(l)):
        if direction == 1:
            if l[i] < l[i-1]:
                return False
        elif direction == -1:
            if l[i] > l[i-1]:
                return False
    return True

